<template>
  <div class="page-wrap candidate-detail" data-testid="candidate-detail-page">
    <div v-if="loading" class="panel detail-loading"><a-icon type="loading" /> 正在读取回放证据</div>
    <a-alert v-else-if="error" type="error" show-icon message="候选证据读取失败" :description="error" />
    <template v-else-if="detail">
      <div class="detail-breadcrumb"><button @click="$router.push('/candidates')"><a-icon type="arrow-left" /> 候选验证</button><span>/</span><span>{{ candidate.name }}</span></div>
      <header class="detail-header"><div class="detail-title"><span class="strategy-icon large"><a-icon type="experiment" /></span><div><div class="title-line"><h1>{{ candidate.name }}</h1><span class="status-tag accepted">回放成功</span></div><code>{{ candidate.strategy_id }}@{{ candidate.version }}</code><p>{{ candidate.summary }}</p></div></div><span v-if="!canReview" class="read-only-label"><a-icon type="eye" /> 只读查看</span></header>

      <section class="approval-rail panel" data-testid="approval-state-rail"><div><small>1 · 回放运行</small><b class="positive">回放成功</b><span>证据包已冻结</span></div><div><small>2 · 证据复核</small><b>{{ stateLabel(review.state) }}</b><span>不改变回放结果</span></div><div><small>3 · 治理决定</small><b>{{ stateLabel(governance.state) }}</b><span>{{ governance.package_id ? '治理包已绑定' : '尚未生成治理包' }}</span></div><div><small>4 · 执行授权</small><b class="negative">未授权</b><span>治理准入也不自动授权</span></div></section>

      <div class="approval-workspace">
        <section class="panel action-panel" data-testid="review-actions"><div class="panel-head"><div><h2>证据复核</h2><p>复核当前证据包的完整性、可复现性与风险说明</p></div><span :class="['status-tag', stateClass(review.state)]">{{ stateLabel(review.state) }}</span></div><div class="action-panel-body"><p>{{ reviewGuidance }}</p><div v-if="canReview" class="review-actions"><a-button v-for="action in review.available_actions" :key="action" :type="action === 'approve-review' ? 'primary' : 'default'" :icon="actionIcon(action)" :loading="submitting" @click="triggerAction('review', action)">{{ actionLabel(action) }}</a-button></div><span v-else class="read-only-label"><a-icon type="eye" /> 当前角色不能执行复核动作</span></div></section>
        <section class="panel action-panel" data-testid="governance-actions"><div class="panel-head"><div><h2>治理审批</h2><p>仅管理员可作治理退回、拒绝或准入决定</p></div><span :class="['status-tag', stateClass(governance.state)]">{{ stateLabel(governance.state) }}</span></div><div class="action-panel-body"><p>{{ governanceGuidance }}</p><div v-if="canGovern" class="review-actions"><a-button v-for="action in governance.available_actions" :key="action" :type="action === 'admit-governance' ? 'primary' : 'default'" :icon="actionIcon(action)" :loading="submitting" @click="triggerAction('governance', action)">{{ actionLabel(action) }}</a-button></div><span v-else class="read-only-label"><a-icon type="lock" /> {{ canReview ? '操作员可复核，但不能作治理决定' : '当前角色不能执行治理动作' }}</span></div></section>
      </div>
      <ReplayJobs :user="user" />
      <a-alert v-if="candidate.external_conformance" class="research-alert" type="warning" show-icon message="与 QuantDinger 原生执行存在一笔受治理差异" :description="`${candidate.external_conformance.governed_execution_difference} Quanthus 原因码：security_not_trading_observed。`" />

      <div class="detail-metrics"><div><span>总收益</span><b :class="candidate.total_return >= 0 ? 'positive' : 'negative'">{{ signed(candidate.total_return) }}</b><small>固定研究单元</small></div><div><span>最大回撤</span><b>{{ percent(candidate.max_drawdown) }}</b><small>历史峰值回撤</small></div><div><span>胜率</span><b>{{ percent(performance.win_rate) }}</b><small>{{ candidate.closed_trades }} 笔闭合交易</small></div><div><span>Sharpe</span><b>{{ number(performance.sharpe_ratio, 3) }}</b><small>日频年化</small></div><div><span>盈亏比</span><b>{{ number(performance.profit_factor, 2) }}</b><small>Profit factor</small></div><div><span>总费用</span><b>{{ money(performance.total_fees) }}</b><small>佣金与税费</small></div></div>
      <section class="panel detail-chart"><div class="panel-head"><div><h2>权益曲线</h2><p>真实回放月末权益，初始权益归一为 100</p></div><span>{{ evidence.equity_curve.length }} 个观测点</span></div><EquityChart :strategy="candidate" :equity-curve="evidence.equity_curve" /></section>
      <div class="detail-grid"><section class="panel"><div class="panel-head"><div><h2>策略与参数</h2><p>本次回放冻结输入</p></div><a-icon type="sliders" /></div><dl class="fact-list"><div v-for="(value, key) in evidence.parameters" :key="key"><dt>{{ parameterLabel(key) }}</dt><dd>{{ value }}</dd></div></dl></section><section class="panel"><div class="panel-head"><div><h2>数据与运行血缘</h2><p>可复现身份</p></div><a-icon type="branches" /></div><dl class="fact-list"><div><dt>数据快照</dt><dd>{{ manifest.data_snapshot_id }}</dd></div><div><dt>执行口径</dt><dd>{{ manifest.execution_profile_id }}</dd></div><div><dt>执行策略</dt><dd>{{ manifest.execution_policy_version }}</dd></div><div><dt>运行 ID</dt><dd class="mono-wrap">{{ manifest.run_id }}</dd></div><div><dt>证据文件</dt><dd class="mono-wrap">{{ evidence.source_artifact_sha256 }}</dd></div><div><dt>实盘授权</dt><dd class="negative">未授权</dd></div></dl></section></div>
      <section class="panel run-history" data-testid="run-history"><div class="panel-head"><div><h2>Run 历史</h2><p>已封存运行只读保留，当前证据由 active 标记识别</p></div><span>{{ runHistory.length }} 条</span></div><div v-if="runHistory.length" class="run-history-table"><table><thead><tr><th>状态</th><th>Run</th><th>完成时间</th><th>收益</th><th>回撤</th><th>证据摘要</th></tr></thead><tbody><tr v-for="run in runHistory" :key="run.run_id"><td><span :class="['status-tag', run.active ? 'accepted' : 'locked']">{{ run.active ? '当前有效' : '历史保留' }}</span></td><td><code>{{ run.run_id }}</code><small>{{ run.job_id }}</small></td><td>{{ dateTime(run.created_at) }}</td><td :class="Number(run.summary.total_return) >= 0 ? 'positive' : 'negative'">{{ signed(run.summary.total_return) }}</td><td>{{ percent(run.summary.maximum_drawdown) }}</td><td><code>{{ shortDigest(run.evidence_digest) }}</code></td></tr></tbody></table></div><a-empty v-else description="尚无 PostgreSQL 已封存 Run" /></section>
      <section v-if="expertEvidence.state !== 'not_applicable'" class="expert-evidence" data-testid="expert-evidence"><div class="expert-section-head"><div><span class="eyebrow">Formal expert evidence</span><h2>专家证据</h2><p v-if="expertEvidence.state === 'available'">{{ expertEvidence.strategy_binding.strategy_id }}@{{ expertEvidence.strategy_binding.strategy_version }}</p></div><span :class="['status-tag', expertEvidence.lifecycle_decision ? 'accepted' : expertEvidence.state === 'available' ? 'control' : 'rejected']">{{ expertEvidenceStateLabel }}</span></div><a-alert v-if="expertEvidence.state === 'not_available'" type="warning" show-icon message="专家证据尚不可用" :description="expertEvidence.reason_codes.join(' · ')" /><template v-else-if="expertEvidence.state === 'available'"><div class="expert-binding"><div><span>证据包</span><code :title="expertEvidence.strategy_binding.package_digest">{{ shortDigest(expertEvidence.strategy_binding.package_digest) }}</code></div><div><span>评估 Run</span><code :title="expertEvidence.strategy_binding.evaluation_run_id">{{ shortDigest(expertEvidence.strategy_binding.evaluation_run_id) }}</code></div><div><span>归因发布</span><code :title="expertEvidence.strategy_binding.attribution_release_id">{{ expertEvidence.strategy_binding.attribution_release_id }}</code></div><div><span>执行授权</span><b class="negative">未授权</b></div></div><div class="expert-table" role="table" aria-label="专家评估"><div class="expert-table-head" role="row"><span>专家与角色</span><span>评估质量</span><span>覆盖 / 弃权</span><span>决策影响</span></div><div v-for="expert in expertEvidence.experts" :key="expert.expert_id" class="expert-row" role="row"><div data-label="专家与角色"><b>{{ expertLabel(expert.expert_id) }}</b><code>{{ expert.expert_id }}@{{ expert.expert_version }}</code><span class="status-tag accepted">{{ expert.mode === 'active' ? 'Active' : 'Shadow' }}</span></div><div data-label="评估质量"><b>{{ primaryMetricDisplay(expertScorecard(expert.expert_id)) }}</b><small>{{ metricLabel(expert.target) }}</small></div><div data-label="覆盖 / 弃权"><b>{{ ratio(expert.coverage) }} / {{ ratio(expert.abstention) }}</b><small>{{ expert.applicability.start }} 至 {{ expert.applicability.end }}</small></div><div data-label="决策影响"><b>{{ classificationLabel(expert.decision_change_summary.classification) }}</b><small>{{ decisionChangeDisplay(expert.decision_change_summary.counts) }}</small></div></div></div><div class="expert-subsection"><div class="expert-subhead"><h3>完整策略经济效应</h3><span>反事实完整 P2 回放</span></div><div class="effect-table"><div v-for="effect in expertEvidence.economic_effects" :key="effect.intervention_id" class="effect-row"><div><b>{{ interventionLabel(effect.intervention_id) }}</b><code>{{ effect.intervention_id }}</code></div><div><span>收益效应</span><b>{{ effectMetricDisplay(effect, 'capital_constrained_net_total_return_delta') }}</b></div><div><span>回撤效应</span><b>{{ effectMetricDisplay(effect, 'maximum_drawdown_delta') }}</b></div><span :class="['status-tag', effect.classification === 'beneficial' ? 'accepted' : 'locked']">{{ classificationLabel(effect.classification) }}</span></div></div></div><div class="expert-two-column"><div class="expert-subsection"><div class="expert-subhead"><h3>预选分歧案例</h3><span>{{ expertEvidence.disagreement_cases.length }} 条</span></div><div class="case-list"><div v-for="item in expertEvidence.disagreement_cases" :key="item.case_id"><div><b>{{ item.market_date }} · {{ expertLabel(item.expert_id) }}</b><code>{{ shortDigest(item.decision_key) }}</code></div><p><span>{{ actionLabelText(item.native.action) }} · {{ item.native.target_maximum_position || '无仓位上限' }}</span><a-icon type="arrow-right" /><span>{{ actionLabelText(item.comparison.action) }} · {{ item.comparison.target_maximum_position || '无仓位上限' }}</span></p><small>{{ item.native.reason_codes.join(' / ') }} → {{ item.comparison.reason_codes.join(' / ') }}</small></div></div></div><div class="expert-subsection"><div class="expert-subhead"><h3>生命周期决定</h3><span>{{ expertEvidence.lifecycle_decision ? dateTime(expertEvidence.lifecycle_decision.decided_at) : '尚未记录' }}</span></div><div v-if="expertEvidence.lifecycle_decision" class="lifecycle-decision"><b>{{ lifecycleDecisionLabel(expertEvidence.lifecycle_decision.decision) }}</b><span :class="['status-tag', expertEvidence.lifecycle_decision.shadow_disposition.status === 'enabled' ? 'accepted' : 'locked']">Shadow {{ expertEvidence.lifecycle_decision.shadow_disposition.status === 'enabled' ? '启用' : '停用' }}</span><p>{{ expertEvidence.lifecycle_decision.rationale }}</p><code>{{ shortDigest(expertEvidence.lifecycle_decision.digest) }}</code></div><div v-else class="lifecycle-undecided"><a-icon type="clock-circle" /><div><b>待生命周期决定</b><span>评估与归因已冻结，当前版本尚未进入 Forward Shadow。</span></div></div></div></div><details class="expert-limitations"><summary>证据限制（{{ expertEvidence.limitations.length }}）</summary><ul><li v-for="item in expertEvidence.limitations" :key="item">{{ item }}</li></ul></details></template></section>
      <section class="panel trade-ledger" data-testid="trade-ledger"><div class="panel-head"><div><h2>成交明细</h2><p>{{ filteredTrades.length }} / {{ evidence.trades.length }} 笔闭合交易</p></div><div class="trade-tools"><a-input-search v-model="tradeQuery" placeholder="搜索证券代码" allow-clear /><a-select v-model="tradeFilter"><a-select-option value="all">全部盈亏</a-select-option><a-select-option value="profit">盈利交易</a-select-option><a-select-option value="loss">亏损交易</a-select-option></a-select></div></div><div class="trade-table-wrap"><table><thead><tr><th>证券</th><th>入场</th><th>退出</th><th>持有</th><th>数量</th><th>收益率</th><th>盈亏</th><th>费用</th></tr></thead><tbody><tr v-for="trade in pagedTrades" :key="`${trade.security_code}-${trade.entry_date}-${trade.exit_date}`"><td><code>{{ trade.security_code }}</code></td><td>{{ trade.entry_date }}</td><td>{{ trade.exit_date }}</td><td>{{ trade.holding_sessions }} 日</td><td>{{ trade.entry_quantity.toLocaleString() }}</td><td :class="trade.return_rate >= 0 ? 'positive' : 'negative'">{{ signed(trade.return_rate) }}</td><td :class="trade.pnl >= 0 ? 'positive' : 'negative'">{{ money(trade.pnl) }}</td><td>{{ money(trade.fees) }}</td></tr></tbody></table></div><div class="table-pagination"><span>第 {{ page }} / {{ totalPages }} 页</span><div><a-button icon="left" :disabled="page <= 1" @click="page--" /><a-button icon="right" :disabled="page >= totalPages" @click="page++" /></div></div></section>
      <section class="panel review-history"><div class="panel-head"><div><h2>审批事件</h2><p>追加式事件流，不覆盖历史证据与决定</p></div><span>{{ approval.history.length }} 条</span></div><div v-if="approval.history.length" class="timeline"><div v-for="item in [...approval.history].reverse()" :key="item.event_id"><i></i><div><b>{{ actionLabel(item.action) }} · {{ item.axis === 'governance' ? '治理' : '复核' }}</b><span>{{ item.actor_username }} · {{ dateTime(item.created_at) }}</span><p v-if="item.note">{{ item.note }}</p><code v-if="item.package_id">{{ item.package_id }}</code></div></div></div><a-empty v-else description="尚无审批事件" /></section>
      <details v-if="expertEvidence.state === 'available'" class="expert-limitations expert-sources" data-testid="expert-source-digests"><summary>专家证据来源摘要（{{ Object.keys(expertEvidence.source_digests).length }}）</summary><dl><div v-for="(value, key) in expertEvidence.source_digests" :key="key"><dt>{{ key }}</dt><dd><code :title="sourceDigest(value)">{{ sourceDigest(value) }}</code></dd></div></dl></details>
      <a-modal v-model="modalOpen" data-testid="approval-modal" :title="actionLabel(modalAction)" :confirm-loading="submitting" ok-text="确认" cancel-text="取消" @ok="submitAction"><p class="modal-copy">{{ modalCopy }}</p><a-input v-model="note" type="textarea" :rows="5" placeholder="请输入至少 8 个字符的审批意见" /></a-modal>
    </template>
  </div>
</template>
<script>
import EquityChart from '../components/EquityChart.vue'
import ReplayJobs from '../components/ReplayJobs.vue'
import { loadCandidate, recordCandidateGovernance, recordCandidateReview } from '../api'

const LABELS = { 'pending-review': '待复核', reviewing: '复核中', 'changes-requested': '待补证', 'review-passed': '复核通过', 'review-failed': '复核未通过', 'governance-not-submitted': '未提交治理', 'governance-under-review': '治理审查中', 'governance-returned': '治理退回', 'governance-withdrawn': '已撤回', 'governance-rejected': '治理拒绝', 'governance-admitted': '治理准入' }
const ACTIONS = { 'claim-review': '认领复核', 'request-changes': '要求补证', 'approve-review': '复核通过', 'reject-review': '复核不通过', 'submit-governance': '提交治理', 'return-governance': '退回治理', 'resubmit-governance': '重新提交治理', 'withdraw-governance': '撤回治理', 'reject-governance': '治理拒绝', 'admit-governance': '治理准入' }

export default {
  components: { EquityChart, ReplayJobs }, props: { user: { type: Object, default: () => ({}) } },
  data: () => ({ detail: null, loading: true, error: '', submitting: false, modalOpen: false, modalAxis: '', modalAction: '', note: '', tradeQuery: '', tradeFilter: 'all', page: 1, pageSize: 20 }),
  computed: {
    candidate () { return this.detail.candidate }, evidence () { return this.detail.evidence }, expertEvidence () { return this.detail.expert_evidence || { state: 'not_applicable', experts: [], assessment_scorecards: [], economic_effects: [], disagreement_cases: [], limitations: [], source_digests: {}, reason_codes: [] } }, approval () { return this.detail.approval }, runHistory () { return this.detail.run_history || [] }, review () { return this.approval.review }, governance () { return this.approval.governance }, performance () { return this.evidence.performance }, manifest () { return this.evidence.run_manifest }, canReview () { return ['admin', 'operator'].includes(this.user.role) }, canGovern () { return this.user.role === 'admin' },
    expertEvidenceStateLabel () { return this.expertEvidence.state === 'not_available' ? '证据不可用' : this.expertEvidence.lifecycle_decision ? '已形成决定' : '待生命周期决定' },
    reviewGuidance () { return ({ 'pending-review': '认领后进入复核；认领不是重跑。', reviewing: '可要求新证据、判定复核通过或判定复核失败。', 'changes-requested': '当前证据包已封口，必须由新的 Run 产生新证据包后才能重新复核。', 'review-passed': '当前证据包已通过复核，可以提交治理。', 'review-failed': '当前证据包复核失败，不能提交治理。' }[this.review.state] || '') },
    governanceGuidance () { return ({ 'governance-not-submitted': '复核通过后才可生成并提交治理包。', 'governance-under-review': '管理员可退回补充复核、拒绝、准入；也可撤回当前提交。', 'governance-returned': '退回会使复核重新待办；新的复核通过后才能重新提交。', 'governance-withdrawn': '当前治理提交已撤回，复核仍有效时可以重新提交。', 'governance-rejected': '该候选版本治理拒绝，决定不可逆；策略变化需创建新版本。', 'governance-admitted': '该候选版本已治理准入，但仍未获得执行授权。' }[this.governance.state] || '') },
    modalCopy () { return this.modalAction === 'admit-governance' ? '治理准入仅确认候选版本可进入后续治理范围，不会授予执行权限。' : '该意见将追加到当前证据包的审批事件中，历史记录不会被覆盖。' },
    filteredTrades () { const q = this.tradeQuery.trim(); return this.evidence.trades.filter(t => (!q || t.security_code.includes(q)) && (this.tradeFilter === 'all' || (this.tradeFilter === 'profit' ? t.pnl >= 0 : t.pnl < 0))) }, totalPages () { return Math.max(1, Math.ceil(this.filteredTrades.length / this.pageSize)) }, pagedTrades () { const safePage = Math.min(this.page, this.totalPages); return this.filteredTrades.slice((safePage - 1) * this.pageSize, safePage * this.pageSize) }
  },
  watch: { tradeQuery () { this.page = 1 }, tradeFilter () { this.page = 1 }, '$route.params.strategyId': 'load' }, created () { this.load() },
  methods: {
    async load () { this.loading = true; this.error = ''; try { this.detail = await loadCandidate(this.$route.params.strategyId) } catch (error) { this.error = error.message || 'request_failed' } finally { this.loading = false } },
    triggerAction (axis, action) { this.modalAxis = axis; this.modalAction = action; this.note = ''; if (action === 'claim-review') this.submitAction(); else this.modalOpen = true },
    async submitAction () { if (this.modalAction !== 'claim-review' && this.note.trim().length < 8) { this.$message.warning('请填写至少 8 个字符的审批意见'); return } this.submitting = true; try { const call = this.modalAxis === 'review' ? recordCandidateReview : recordCandidateGovernance; await call(this.candidate.strategy_id, this.modalAction, this.note); this.modalOpen = false; await this.load(); this.$emit('catalog-changed'); this.$message.success(`${this.actionLabel(this.modalAction)}已记录`) } catch (error) { this.$message.error(error.message || '操作失败') } finally { this.submitting = false } },
    stateLabel: state => LABELS[state] || state, actionLabel: action => ACTIONS[action] || action,
    expertScorecard (expertId) { return this.expertEvidence.assessment_scorecards.find(item => item.assessment_id === expertId) || {} },
    expertLabel: id => ({ 'expert.trend-stability': '趋势稳定专家', 'expert.position-risk-review': '持仓风控专家' }[id] || id),
    metricLabel: id => ({ 'metric.mean-absolute-ordinal-error': '平均绝对序数误差', 'metric.decision-change-rate': '决策变化率' }[id] || id),
    primaryMetricDisplay (scorecard) { const metric = scorecard.primary_metric || {}; if (metric.display) return metric.display.intervention || metric.display.raw_effect || '—'; return metric.value == null ? '—' : Number(metric.value).toFixed(4) },
    ratio: value => value == null ? '—' : `${(Number(value) * 100).toFixed(1)}%`,
    classificationLabel: value => ({ beneficial: '有利', harmful: '有害', negligible: '可忽略', unoriented: '无方向', unallocated: '不分摊', valid: '有效' }[value] || value),
    decisionChangeDisplay (counts) { if (!counts) return '—'; if (counts.changed != null) return `${counts.changed.toLocaleString()} 次变化`; return `${Number(counts.evaluated || 0).toLocaleString()} 个评估样本` },
    interventionLabel: id => ({ 'intervention.trend-stability-abstain': '趋势专家单独效应', 'intervention.position-risk-base-policy': '持仓风控单独效应', 'intervention.both-experts-fallback': '双专家联合效应', 'interaction.unallocated': '专家交互项（不分摊）' }[id] || id),
    effectMetricDisplay (effect, metricId) { const metric = effect.metrics?.[metricId]; if (metric?.display) return metric.display.oriented_effect || metric.display.raw_effect || '—'; if (metric == null) return '—'; return `${Number(metric) >= 0 ? '+' : ''}${(Number(metric) * 100).toFixed(2)} pp` },
    actionLabelText: value => ({ trial_entry: '试仓', no_action: '不动作', reduce: '减仓', exit: '退出', hold: '持有' }[value] || value),
    lifecycleDecisionLabel: value => ({ keep: '保留当前版本', narrow_with_new_version: '收窄并新建版本', remap_policy: '重映射策略', merge: '合并专家', retire: '退役', inconclusive: '证据不足' }[value] || value),
    actionIcon: action => ({ 'claim-review': 'audit', 'request-changes': 'rollback', 'approve-review': 'check', 'reject-review': 'close', 'submit-governance': 'send', 'return-governance': 'rollback', 'resubmit-governance': 'send', 'withdraw-governance': 'export', 'reject-governance': 'stop', 'admit-governance': 'safety-certificate' }[action] || 'edit'),
    stateClass: state => state.includes('passed') || state.includes('admitted') ? 'accepted' : state.includes('failed') || state.includes('rejected') || state.includes('changes') || state.includes('returned') ? 'rejected' : state.includes('not-submitted') || state.includes('withdrawn') ? 'locked' : 'control',
    percent: v => v == null ? '—' : `${Number(v).toFixed(2)}%`, signed: v => v == null ? '—' : `${Number(v) >= 0 ? '+' : ''}${Number(v).toFixed(2)}%`, number: (v, digits) => v == null ? '—' : Number(v).toFixed(digits), money: v => Number(v).toLocaleString('zh-CN', { style: 'currency', currency: 'CNY', minimumFractionDigits: 2 }), dateTime: v => new Date(v).toLocaleString('zh-CN', { hour12: false }), shortDigest: v => v ? `${v.slice(0, 16)}...${v.slice(-8)}` : '—', sourceDigest: value => value && typeof value === 'object' ? JSON.stringify(value) : String(value || '—'),
    parameterLabel: key => ({ portfolio_units: '研究单元', capital_per_unit: '单元资金', execution_profile: '执行口径', selection: '选股规则', short_period: '短均线周期', mid_period: '中均线周期', long_period: '长均线周期', min_body_pct: '最小阳线实体', target_pct: '目标仓位', lot_size: '交易手数', maximum_holding_sessions: '最长持有日', minimum_momentum20: '最小 20 日动量', maximum_momentum20: '最大 20 日动量', entry_rsi_floor: '入场 RSI 下限', entry_rsi_ceiling: '入场 RSI 上限', exit_rsi_floor: '退出 RSI 下限' }[key] || key.replaceAll('_', ' '))
  }
}
</script>
